// A tiny new-space model. Allocation is a pointer bump; overflow triggers a Scavenge.
const LIMIT = 64;     // semi-space capacity in bytes
const OBJ = 16;       // each object is 16 bytes

let top = 0;
let allocations = 0;
let scavenges = 0;

function allocate() {
  if (top + OBJ > LIMIT) {  // would pass the limit -> semi-space full
    scavenges++;
    top = 0;                // Scavenge: survivors evacuated, space reset
  }
  const addr = top;
  top += OBJ;               // the whole fast-path allocation
  allocations++;
  return addr;
}

for (let i = 0; i < 10; i++) allocate();
console.log('alloc=' + allocations + ' scavenges=' + scavenges);

// 'Optimization': reuse a fixed pool of scratch objects across requests
const POOL = Array.from({ length: 10000 }, () => ({ a: 0, b: 0, c: 0 }));
let idx = 0;
function getScratch() {
  const o = POOL[idx]; idx = (idx + 1) % POOL.length;
  o.a = 0; o.b = 0; o.c = 0; // reset
  return o;
}
// ...used once per request and then discarded conceptually
